/**
 * Map from an "additional" (ECNO) indicator id to the ESABCC indicator
 * that covers the same concept. Built by scanning ESABCC_REPORT_INDICATORS
 * for `duplicateOf` references so the UI can flag both sides of the pair.
 */
export const ECNO_TO_ESABCC_DUPLICATE: Readonly<Record<string, string>> =
  Object.freeze(
    ESABCC_REPORT_INDICATORS.reduce<Record<string, string>>((acc, i) => {
      if (i.duplicateOf) acc[i.duplicateOf] = i.id;
      return acc;
    }, {})
  );
